void NetCtrlAdaptor::initServer()
{
    bool isServiceRegistered = QDBusConnection::systemBus().interface()->isServiceRegistered(QStringLiteral("com.kylin.networkCtrol"));
    if(!isServiceRegistered)
    {
       registerService();
    }
}

void NetCtrlAdaptor::initCfg()
{

    mCfgHandle=kylinCfgCreate();
    if(mCfgHandle)
    {
         if(kylinCfgLoad(mCfgHandle,QString(KYLIN_NETCTROL_CFG_PATH).toLocal8Bit().data())==COMMON_FILE_NOT_EXIST)
         {
             fristCreatCfgInfo();
             kylinCfgFlush(mCfgHandle);//配置文件在dbus服务端刷合理点
         }
         kylinCfgShow(mCfgHandle);
    }
    else
    {
        KYLIN_COMMON_LOG(_LOGL_ERR,"create failed!");
    }
}

// LCOV_EXCL_START
bool NetCtrlAdaptor::registerService()
{

    QDBusConnection conn = QDBusConnection::systemBus();
    auto reply = conn.interface()->registerService(QStringLiteral("com.kylin.networkCtrol"),
                                                          QDBusConnectionInterface::ReplaceExistingService,
                                                          QDBusConnectionInterface::DontAllowReplacement);
    if (reply.value() == QDBusConnectionInterface::ServiceNotRegistered) {
        KYLIN_COMMON_LOG(_LOGL_ERR,"registerService /com/kylin/networkCtrol failed!");
        return false;
    }

    bool res = QDBusConnection::systemBus().registerObject("/com/kylin/networkCtrol", this,QDBusConnection::ExportAllSlots | QDBusConnection::ExportAllSignals);
    if (!res) {
        QDBusConnection::systemBus().interface()->unregisterService(QStringLiteral("com.kylin.networkCtrol"));
        KYLIN_COMMON_LOG(_LOGL_ERR,"registerObject /com/kylin/networkCtrol failed!");
    }
    KYLIN_COMMON_LOG(_LOGL_INFO,"registerObject /com/kylin/networkCtrol success!");

    return res;
}
