GVariant* NetCtrlAdaptor::transQvariantToGvariant(QVariant &qVariant)
{
    GVariant* gVariant = nullptr;

    switch (qVariant.type()) {
    case QVariant::Int:
        gVariant = g_variant_new_int32(qVariant.toInt());
        break;
    case QVariant::UInt:
        gVariant = g_variant_new_uint32(qVariant.toUInt());
        break;
    case QVariant::Bool:
        gVariant = g_variant_new_boolean(qVariant.toBool());
        break;
    case QVariant::Double:
        gVariant = g_variant_new_double(qVariant.toDouble());
        break;
    case QVariant::String:
        gVariant = g_variant_new_string(qVariant.toString().toLocal8Bit().data());
        break;
    // 添加其他QVariant类型的转换
    default:
        // 其他类型TODO
        // 默认情况下，不支持的类型返回NULL
        gVariant = nullptr;
        break;
    }
    return gVariant;
}

