int NetCtrlAdaptor::setNetContrlRule(const QString modName,const QVariantMap value)
{
    KYLIN_COMMON_LOG(_LOGL_INFO,"setNetContrlRule ruleName:%s \n",modName.toLocal8Bit().data());
    GVariant* gVariant = nullptr;
    QString msg;

    if(value.isEmpty() || modName.isEmpty())
    {
        KYLIN_COMMON_LOG(_LOGL_ERR,"setNetContrlRule invalid parm");
        return NETCT_INVALID_MODE;
    }

    for (auto it = value.cbegin(); it != value.cend(); ++it) {
        QString key = it.key();
        QVariant value = it.value();


        KYLIN_COMMON_LOG(_LOGL_INFO,"map item value:%s",value.toString().toLocal8Bit().data());//注意这里只有基本类型才能这样打印出值 否则是空字符串

        st_ItemCfgInfo *pItemCfgInfo=kylinCfgGetItem(mCfgHandle,modName.toLocal8Bit().data(),key.toLocal8Bit().data());
        if(!pItemCfgInfo)
        {
            KYLIN_COMMON_LOG(_LOGL_ERR,"not support modName:%s",modName.toLocal8Bit().data());
            msg=QString().sprintf("set %s failed,not support",modName.toLocal8Bit().data());;
            return NETCT_INVALID_RULE;
        }

        if(pItemCfgInfo->dataType==KEYLIN_CFG_VARIANT)
        {
            gVariant=transQvariantToGvariant(value);
            if(!gVariant)
            {
                return NETCT_PARM_MISMATCH;
            }

            gboolean ret=g_variant_equal(gVariant,(GVariant*)pItemCfgInfo->data);
            if(!ret)
            {
                st_ItemCfgInfo *pItemCfgInfo=kylinCfgNewCommonItem(modName.toLocal8Bit().data(),key.toLocal8Bit().data(),gVariant);
                if(kylinCfgSetItem(mCfgHandle,pItemCfgInfo))
                {
                    return NETCT_DO_FAILED;
                }
            }
            else
            {
                g_variant_unref(gVariant);
            }
        }
        else
        {
            KYLIN_COMMON_LOG(_LOGL_ERR,"not support");
            //TODO 需要自己加自定义数据转换 暂时没用到
        }
    }
    kylinCfgFlush(mCfgHandle);//刷配置文件
    Q_EMIT sigNetContrlRuleChanged(modName,value);
    return NETCT_SUCCESS;
}

void  NetCtrlAdaptor::getNetContrlRule(const QString modName,QVariantMap &value,int &errCode)
{
    GList * list=NULL, *iter=NULL;
    errCode=0;
   // kylinCfgGetItem(mCfgHandle,modName.toLocal8Bit().data(),);
    KYLIN_COMMON_LOG(_LOGL_INFO,"getNetContrlRule modName:%s",modName.toLocal8Bit().data());
    list=kylinCfgGetModItems(mCfgHandle,modName.toLocal8Bit().data());
    if(!list)
    {
        errCode=NETCT_INVALID_MODE;
        return;
    }

    for (iter = list; iter; iter = iter->next)
    {
       //KYLIN_COMMON_LOG(_LOGL_DEBUG,"getNetContrlRule iter:%p ",iter);
       st_ItemCfgInfo *pItemCfgInfo=( st_ItemCfgInfo *)iter->data;
       if(pItemCfgInfo->dataType==KEYLIN_CFG_VARIANT)
       {
           QVariant data=transGvariantToQvariant((GVariant*)pItemCfgInfo->data);
           if(data.isNull())
           {
                KYLIN_COMMON_LOG(_LOGL_ERR,"getNetContrlRule ruleName:%s ",modName.toLocal8Bit().data());
                errCode=NETCT_PARM_MISMATCH;
               break;
           }
           KYLIN_COMMON_LOG(_LOGL_DEBUG,"getNetContrlRule insert modName:%s",pItemCfgInfo->itemName);
           value.insert(QString(pItemCfgInfo->itemName),data);
       }
       else
       {
           KYLIN_COMMON_LOG(_LOGL_ERR,"getNetContrlRule ruleName:%s",modName.toLocal8Bit().data());
           errCode=NETCT_PARM_MISMATCH;
           //TODO 需要自己加自定义数据转换 暂时没用到
           break;
       }
    }

    g_list_free(list);
    return ;
}

