void NetCtrlAdaptor::clearBackMessage()
{
    mType=0;
    mMessage=QString("");
    mErrcode=0;
    return ;
}


int NetCtrlAdaptor::waitNetCtrlBackResult(unsigned long long timeOutMs,QString cmd)
{
    unsigned long long startTime=kylinGetSysRtime();
    while((kylinGetSysRtime()-startTime)<timeOutMs) {
        if(mType && mMessage==cmd) {
            return 0;
        }
        QThread::msleep(1);
    }

    KYLIN_COMMON_LOG(_LOGL_WARN,"wait back result time out:%lld ",timeOutMs);
    return -1;
}

int NetCtrlAdaptor::sendNetCtrLog(int errcode,int type,QString message)
{
    KYLIN_COMMON_LOG(_LOGL_INFO,"recv %d type:%d message:%s\n",errcode,type,message.toLocal8Bit().data());
    QString level;

 // type类型NETCONTROL_LOG_TYPE 预留拓展
 //域控日志收集平台需要level固定为error
   level=QString("error");
   struct T_NetCtrlLogInfo *pNetCtrlLogInfo=( struct T_NetCtrlLogInfo *)malloc(sizeof(struct T_NetCtrlLogInfo));
   pNetCtrlLogInfo->level=g_strdup(level.toLocal8Bit().data());
   pNetCtrlLogInfo->messag=g_strdup(message.toLocal8Bit().data());
   kylinAsyncTaskAdd(mAsyncHandle,netCtrlAsyncSendHedronLog,pNetCtrlLogInfo);//qt有其他实现，此处使用自研代码实现，为后面迭代

   return 0;
}

